/**
 * The chat composer, where a prompt is written and sent (`design/components/prompt-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/prompt-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  Icon,
  afterRender,
  agentFill,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  fitTextarea,
  gateFiles,
  promptPick,
  promptToken,
  scope,
  watchEffect,
  type Defaults,
  type FileRejection,
  type IconRole,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/prompt-input.module.css'
import AttachmentChip, { type AttachmentStatus } from './AttachmentChip'
import Button from '../controls/Button'
import Skeleton from '../structure/Skeleton'

export type PromptInputMaxRows = NonNullable<PromptInputProps['maxRows']>

export interface PromptAttachment {
  id: string
  name: string
  size?: number
  status?: AttachmentStatus
  message?: string
}

export interface PromptInputMessages {
  send: string
  stop: string
  attach: string
  remove: (name: string) => string
  uploading: (name: string) => string
  suggestions?: (count: number) => string
  loadingSuggestions?: string
  noSuggestions?: string
}

export interface PromptTriggerOption {
  id: string
  label: string
  description?: string
  icon?: IconRole
  insert?: string
}

export interface PromptTrigger {
  char: string
  label: string
  options: PromptTriggerOption[]
  at?: 'word' | 'start'
  filter?: 'contains' | 'startsWith' | false
  loading?: boolean
  onQueryChange?: (query: string) => void
  onSelect?: (option: PromptTriggerOption) => void
}

export interface PromptInputProps {
  /**
   * The native `accept` syntax (`.pdf`, `image/*`), also applied to drops and pastes.
   */
  accept?: string
  /**
   * The chips in the frame, always controlled by the app.
   */
  attachments?: PromptAttachment[]
  /**
   * Native passthrough, for a screen that has already moved the reader here.
   */
  autoFocus?: boolean
  defaultValue?: string
  disabled?: boolean
  /**
   * One line under the frame with the app's own note about what happens next.
   */
  hint?: string
  id?: string
  /**
   * The field's accessible name, needed because a composer has no visible label.
   */
  label: string
  /**
   * The toolbar's start slot for `sm` vocabulary controls, such as a model Select or a tools
   * Menu.
   */
  leading?: JSX.Element
  /**
   * How tall the field may grow before it scrolls, in lines.
   */
  maxRows?: 4 | 6 | 8 | 12
  /**
   * The maximum file size in bytes, above which a file never reaches `onAttach`.
   */
  maxSize?: number
  /**
   * All of the controls' text (generic English defaults), which localized hosts replace.
   */
  messages?: PromptInputMessages
  /**
   * When `false`, only one file is accepted at a time and the rest are rejected as `count`.
   */
  multiple?: boolean
  name?: string
  /**
   * Receives files that passed the gate (from the attach button, a drop or a paste) and shows
   * the attach button.
   */
  onAttach?: (files: File[]) => void
  onChange?: (value: string) => void
  /**
   * Receives the files the gate rejected with their reasons, which the app reports in its own
   * words.
   */
  onReject?: (rejections: FileRejection[]) => void
  onRemoveAttachment?: (id: string) => void
  /**
   * The stop button's handler while `streaming`.
   */
  onStop?: () => void
  /**
   * Called on Enter or the send button, and required because a composer that cannot send is a
   * Textarea.
   */
  onSubmit: (value: string) => void
  placeholder?: string
  /**
   * Whether a reply is arriving, which turns send into stop and makes Enter do nothing.
   */
  streaming?: boolean
  /**
   * The toolbar's end, before the send control.
   */
  trailing?: JSX.Element
  /**
   * The characters that open a list of suggestions: `@` for people, `/` for commands.
   */
  triggers?: PromptTrigger[]
  value?: string
}

/** The chat composer, where a prompt is written and sent. */
export default function PromptInput(given: PromptInputProps): JSX.Element {
  const props = mergeProps(
    {
      streaming: false,
      disabled: false,
      maxRows: 8,
      attachments: (() => [])(),
      triggers: (() => [])(),
      multiple: true,
      autoFocus: false,
      messages: (() => ({
        send: 'Send',
        stop: 'Stop',
        attach: 'Attach',
        remove: (name) => `Remove ${name}`,
        uploading: (name) => `${name}: uploading`,
      }))(),
    } as Defaults<
      PromptInputProps,
      | 'streaming'
      | 'disabled'
      | 'maxRows'
      | 'attachments'
      | 'triggers'
      | 'multiple'
      | 'autoFocus'
      | 'messages'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const uncontrolled = createCell(props.defaultValue ?? '')
    const dragover = createCell(false)
    const caret = createCell(null as number | null)
    const composing = createCell(false)
    const dismissed = createCell(null as number | null)
    const highlight = createCell({ key: '', index: 0 })
    const side = createCell('top' as 'top' | 'bottom')
    const reported = createCell(null as string | null)
    const chips = elementRef<HTMLElement>()
    const end = elementRef<HTMLElement>()
    const field = elementRef<HTMLElement>()
    const picker = elementRef<HTMLElement>()
    const root = elementRef<HTMLElement>()
    const toolbar = elementRef<HTMLElement>()
    const text = createDerived(() => props.value ?? uncontrolled.value)
    const empty = createDerived(() => text.value.trim() === '' && props.attachments.length === 0)
    const attachable = createDerived(() => props.onAttach !== undefined && !props.disabled)
    const setText = createDerived(
      () => (next: string) => ((uncontrolled.value = next), props.onChange?.(next)),
    )
    const submit = createDerived(
      () => () =>
        !props.disabled &&
        !props.streaming &&
        !empty.value &&
        (props.onSubmit?.(text.value), props.value === undefined && (uncontrolled.value = '')),
    )
    const add = createDerived(
      () => (list: FileList | File[] | null | undefined) =>
        attachable.value &&
        list != null &&
        list.length > 0 &&
        ((gate) => (
          gate.accepted.length > 0 && props.onAttach?.(gate.accepted),
          gate.rejected.length > 0 && props.onReject?.(gate.rejected)
        ))(
          gateFiles(Array.from(list), {
            accept: props.accept,
            multiple: props.multiple,
            maxSize: props.maxSize,
          }),
        ),
    )
    const suggesting = createDerived(() => props.triggers.length > 0)
    const token = createDerived(() =>
      props.disabled ? null : promptToken(text.value, caret.value, props.triggers),
    )
    const trigger = createDerived(() =>
      token.value === null ? undefined : props.triggers[token.value.trigger],
    )
    const open = createDerived(
      () =>
        token.value !== null &&
        trigger.value !== undefined &&
        token.value.start !== dismissed.value,
    )
    const query = createDerived(() => token.value?.query ?? '')
    const collator = createDerived(
      () => new Intl.Collator(undefined, { usage: 'search', sensitivity: 'base' }),
    )
    const needle = createDerived(() => query.value.normalize('NFC'))
    const matches = createDerived(
      () => (label: string) =>
        ((candidate: string) =>
          needle.value === '' ||
          (trigger.value?.filter === 'startsWith'
            ? collator.value.compare(candidate.slice(0, needle.value.length), needle.value) === 0
            : Array.from(
                { length: Math.max(0, candidate.length - needle.value.length + 1) },
                (_, at) => candidate.slice(at, at + needle.value.length),
              ).some((part) => collator.value.compare(part, needle.value) === 0)))(
          label.normalize('NFC'),
        ),
    )
    const shown = createDerived(() =>
      !open.value || trigger.value === undefined
        ? []
        : trigger.value.filter === false
          ? trigger.value.options
          : trigger.value.options.filter((option) => matches.value(option.label)),
    )
    const loading = createDerived(() => open.value && trigger.value?.loading === true)
    const listKey = createDerived(() =>
      open.value && token.value !== null
        ? `${token.value.trigger}:${token.value.start}:${query.value}`
        : '',
    )
    const sideKey = createDerived(() =>
      open.value && token.value !== null ? `${token.value.trigger}:${token.value.start}` : null,
    )
    const active = createDerived(() =>
      shown.value.length === 0
        ? -1
        : highlight.value.key === listKey.value
          ? Math.min(highlight.value.index, shown.value.length - 1)
          : 0,
    )
    const listId = createDerived(() => `${uid}-suggestions`)
    const say = createDerived(() => ({
      suggestions: props.messages.suggestions ?? ((count: number) => `${count} suggestions`),
      loadingSuggestions: props.messages.loadingSuggestions ?? 'Loading suggestions…',
      noSuggestions: props.messages.noSuggestions ?? 'No results',
    }))
    const announcement = createDerived(() =>
      !open.value
        ? ''
        : loading.value
          ? say.value.loadingSuggestions
          : shown.value.length === 0
            ? say.value.noSuggestions
            : say.value.suggestions(shown.value.length),
    )
    const track = createDerived(() => (element: HTMLTextAreaElement, nextText: string) => {
      if (composing.value || element.value !== nextText) return
      const next =
        element.ownerDocument.activeElement === element &&
        element.selectionStart === element.selectionEnd
          ? element.selectionStart
          : null
      const found = props.disabled ? null : promptToken(nextText, next, props.triggers)
      const closed = found !== null && found.start === dismissed.value ? dismissed.value : null
      caret.value = next
      dismissed.value = closed
      const key =
        found === null || closed !== null
          ? null
          : found.trigger + ':' + found.start + ':' + found.query
      if (key === reported.value) return
      reported.value = key
      if (found !== null && key !== null)
        props.triggers[found.trigger]?.onQueryChange?.(found.query)
    })
    const pick = createDerived(() => (index: number) => {
      const option = shown.value[index]
      const at = token.value
      const by = trigger.value
      if (option === undefined || at === null || by === undefined || caret.value === null) return
      const next = promptPick(text.value, at, caret.value, option.insert ?? by.char + option.label)
      setText.value(next.text)
      caret.value = next.caret
      dismissed.value = null
      reported.value = null
      afterRender(() =>
        (field.value as HTMLTextAreaElement | null)?.setSelectionRange(next.caret, next.caret),
      )
      by.onSelect?.(option)
    })
    const holdEscape = createDerived(() => (element: HTMLTextAreaElement) => {
      const view = element.ownerDocument.defaultView
      const hold = (event: KeyboardEvent) => {
        if (event.key === 'Escape' && event.target === element && !event.isComposing)
          event.preventDefault()
      }
      view?.addEventListener('keydown', hold, true)
      return () => view?.removeEventListener('keydown', hold, true)
    })
    const listKeys = createDerived(() => (event: KeyboardEvent) => {
      const at = token.value
      if (!open.value || at === null) return false
      if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
        if (shown.value.length === 0) return false
        event.preventDefault()
        highlight.value = {
          key: listKey.value,
          index:
            event.key === 'ArrowDown'
              ? Math.min(active.value + 1, shown.value.length - 1)
              : Math.max(active.value - 1, 0),
        }
        return true
      }
      if (event.key === 'Enter') {
        if (event.shiftKey || (active.value === -1 && !loading.value)) return false
        event.preventDefault()
        if (active.value !== -1) pick.value(active.value)
        return true
      }
      if (event.key === 'Tab') {
        if (event.shiftKey || active.value === -1) return false
        event.preventDefault()
        pick.value(active.value)
        return true
      }
      if (event.key === 'Escape') {
        // Escape closes the list and keeps the text. A dialog around the composer stays open,
        // because holdEscape has prevented the key's default.
        event.preventDefault()
        event.stopPropagation()
        dismissed.value = at.start
        reported.value = null
        return true
      }
      return false
    })
    const effect1 = () => {
      void (field.value && fitTextarea(field.value as HTMLTextAreaElement))
    }
    watchEffect(
      createMemo(() => text.value),
      effect1,
      true,
    )
    const effect2 = () => {
      void (
        props.autoFocus &&
        field.value &&
        (field.value.focus(),
        (field.value as HTMLTextAreaElement).setSelectionRange(
          text.value.length,
          text.value.length,
        ),
        track.value(field.value as HTMLTextAreaElement, text.value))
      )
    }
    onMount(effect2)
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran =
        open.value && field.value ? holdEscape.value(field.value as HTMLTextAreaElement) : () => {}
      release3 = () => {
        ran()
      }
    }
    watchEffect(
      createMemo(() => open.value),
      effect3,
      true,
    )
    onCleanup(() => release3?.())
    const effect4 = () => {
      void (
        sideKey.value !== null &&
        root.value &&
        ((box: DOMRect) =>
          (side.value = box.top >= window.innerHeight - box.bottom ? 'top' : 'bottom'))(
          (root.value as HTMLElement).getBoundingClientRect(),
        )
      )
    }
    watchEffect(
      createMemo(() => sideKey.value),
      effect4,
      true,
    )
    let release5: (() => void) | undefined
    const effect5 = () => {
      release5?.()
      const ran = agentMember({
        member: 'PromptInput',
        element: () => field.value,
        state: () => ({
          value: text.value,
          attachments: props.attachments.map((attachment) => ({
            id: attachment.id,
            label: attachment.name,
            ...(props.onRemoveAttachment !== undefined && !props.disabled
              ? {}
              : { disabled: true }),
          })),
          streaming: props.streaming,
          disabled: props.disabled,
        }),
        actions: {
          fill: { argument: 'text', run: (value) => agentFill(field.value, value) },
          clear: () => agentFill(field.value, ''),
          submit: () =>
            (() => {
              if (props.streaming)
                throw new Error('A reply is arriving; stop it before sending a prompt.')
              if (empty.value)
                throw new Error('The prompt is empty, and an empty prompt is not sent.')
              submit.value()
            })(),
          stop: () =>
            (() => {
              if (!props.streaming)
                throw new Error('No reply is arriving, so there is nothing to stop.')
              props.onStop?.()
            })(),
          remove: { argument: 'id', run: (value) => props.onRemoveAttachment?.(value) },
        },
        withholds: () => [
          chips.value,
          props.onAttach !== undefined ? toolbar.value?.firstElementChild : null,
          end.value?.lastElementChild,
        ],
      })
      release5 = () => {
        ran()
      }
    }
    onMount(effect5)
    onCleanup(() => release5?.())
    return (
      <div
        class={styles.root}
        data-state={props.streaming ? 'streaming' : dragover.value ? 'dragover' : undefined}
        data-disabled={props.disabled ? '' : undefined}
        data-empty={empty.value ? '' : undefined}
        data-max-rows={String(props.maxRows)}
        data-member="prompt-input"
        ref={root.attach}
      >
        {/* frame */}
        <div
          class={styles.frame}
          ondragover={($event: DragEvent) =>
            attachable.value && ($event.preventDefault(), (dragover.value = true))
          }
          ondragleave={($event: DragEvent) =>
            !($event.currentTarget as HTMLElement).contains($event.relatedTarget as Node | null) &&
            (dragover.value = false)
          }
          ondrop={($event: DragEvent) =>
            attachable.value &&
            ($event.preventDefault(),
            (dragover.value = false),
            add.value($event.dataTransfer?.files))
          }
        >
          {props.attachments.length > 0 ? (
            <div class={styles.attachments} ref={chips.attach}>
              <Each of={props.attachments} by={(attachment) => attachment.id} renew>
                {(attachment) => (
                  <>
                    {props.onRemoveAttachment !== undefined && !props.disabled ? (
                      <AttachmentChip
                        name={attachment.name}
                        size={attachment.size}
                        status={attachment.status}
                        message={attachment.message}
                        removeLabel={props.messages.remove(attachment.name)}
                        uploadingLabel={props.messages.uploading(attachment.name)}
                        onRemove={() => props.onRemoveAttachment?.(attachment.id)}
                      />
                    ) : (
                      <AttachmentChip
                        name={attachment.name}
                        size={attachment.size}
                        status={attachment.status}
                        message={attachment.message}
                        removeLabel={props.messages.remove(attachment.name)}
                        uploadingLabel={props.messages.uploading(attachment.name)}
                      />
                    )}
                  </>
                )}
              </Each>
            </div>
          ) : null}
          {/* field */}
          <textarea
            class={styles.field}
            id={props.id}
            name={props.name}
            rows={1}
            value={text.value}
            placeholder={props.placeholder}
            disabled={props.disabled}
            aria-label={props.label}
            aria-autocomplete={suggesting.value ? 'list' : undefined}
            aria-haspopup={suggesting.value ? 'listbox' : undefined}
            aria-controls={open.value ? listId.value : undefined}
            aria-activedescendant={
              open.value && active.value !== -1 ? `${uid}-suggestion-${active.value}` : undefined
            }
            oninput={($event: InputEvent) => (
              setText.value(($event.target as HTMLTextAreaElement).value),
              track.value(
                $event.target as HTMLTextAreaElement,
                ($event.target as HTMLTextAreaElement).value,
              )
            )}
            onkeydown={($event: KeyboardEvent) =>
              !$event.isComposing &&
              !listKeys.value($event) &&
              $event.key === 'Enter' &&
              !$event.shiftKey &&
              ($event.preventDefault(), submit.value())
            }
            onkeyup={($event: KeyboardEvent) =>
              track.value($event.currentTarget as HTMLTextAreaElement, text.value)
            }
            onpointerup={($event: PointerEvent) =>
              track.value($event.currentTarget as HTMLTextAreaElement, text.value)
            }
            onfocus={($event: FocusEvent) =>
              track.value($event.currentTarget as HTMLTextAreaElement, text.value)
            }
            onblur={() => ((caret.value = null), (reported.value = null))}
            oncompositionstart={() => (composing.value = true)}
            oncompositionend={($event: CompositionEvent) => (
              (composing.value = false),
              track.value($event.currentTarget as HTMLTextAreaElement, text.value)
            )}
            onpaste={($event: ClipboardEvent) =>
              attachable.value &&
              ($event.clipboardData?.files.length ?? 0) > 0 &&
              ($event.preventDefault(), add.value($event.clipboardData?.files))
            }
            ref={field.attach}
          />
          {/* toolbar */}
          <div class={styles.toolbar} ref={toolbar.attach}>
            {props.onAttach !== undefined ? (
              <Button
                variant="ghost"
                tone="neutral"
                size="sm"
                iconOnly={true}
                icon="attach"
                label={props.messages.attach}
                disabled={props.disabled}
                onClick={() => picker.value?.click()}
              />
            ) : null}
            {props.leading}
            {/* end */}
            <div class={styles.end} ref={end.attach}>
              {props.trailing}
              {props.streaming ? (
                <Button
                  variant="outline"
                  tone="neutral"
                  size="sm"
                  iconOnly={true}
                  icon="stop"
                  label={props.messages.stop}
                  onClick={() => props.onStop?.()}
                />
              ) : (
                <Button
                  variant="solid"
                  tone="accent"
                  size="sm"
                  iconOnly={true}
                  icon="send"
                  label={props.messages.send}
                  disabled={props.disabled || empty.value}
                  onClick={() => submit.value()}
                />
              )}
            </div>
          </div>
          {props.onAttach !== undefined ? (
            <input
              class={styles.picker}
              type="file"
              accept={props.accept}
              multiple={props.multiple}
              disabled={props.disabled}
              tabindex="-1"
              onchange={($event: Event) => (
                add.value(($event.target as HTMLInputElement).files),
                (($event.target as HTMLInputElement).value = '')
              )}
              ref={picker.attach}
            />
          ) : null}
        </div>
        {props.hint !== undefined ? <p class={styles.hint}>{props.hint}</p> : null}
        {open.value && trigger.value !== undefined ? (
          <div
            class={styles.suggestions}
            data-side={side.value}
            data-prompt-part="suggestions"
            onmousedown={($event: MouseEvent) => $event.preventDefault()}
          >
            {/* list */}
            <ul
              class={styles.listbox}
              id={listId.value}
              role="listbox"
              aria-label={trigger.value?.label}
            >
              <Each of={shown.value} by={(option) => option.id} renew>
                {(option, index) => (
                  <li
                    class={styles.option}
                    id={`${uid}-suggestion-${index()}`}
                    role="option"
                    aria-selected={index() === active.value ? 'true' : 'false'}
                    data-highlighted={index() === active.value ? '' : undefined}
                    onpointermove={() =>
                      index() !== active.value &&
                      (highlight.value = { key: listKey.value, index: index() })
                    }
                    onclick={() => pick.value(index())}
                  >
                    {option.icon !== undefined ? (
                      <span class={styles.glyph}>
                        <Icon name={option.icon} size="sm" />
                      </span>
                    ) : null}
                    <span class={styles.text}>
                      <span class={styles.label}>{option.label}</span>
                      {option.description !== undefined ? (
                        <span class={styles.description}>{option.description}</span>
                      ) : null}
                    </span>
                  </li>
                )}
              </Each>
            </ul>
            {loading.value ? (
              <div class={styles.rows} aria-hidden="true">
                <Each of={[0, 1, 2]} by={(row) => row}>
                  {() => (
                    <div class={styles.row}>
                      <Skeleton textStep="sm" />
                    </div>
                  )}
                </Each>
              </div>
            ) : null}
            {!loading.value && shown.value.length === 0 ? (
              <div class={styles.empty} aria-hidden="true">
                {say.value.noSuggestions}
              </div>
            ) : null}
          </div>
        ) : null}
        {suggesting.value ? (
          <div class={styles.status} role="status" aria-live="polite">
            {announcement.value}
          </div>
        ) : null}
      </div>
    )
  })
}
